import{_ as s,a0 as i,w as o,s as b,I as t,x as p,a1 as e,A as u,ao as m}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const W=JSON.parse('{"title":"Ubuntu 14.04/16.04 与 Windows 10 周年版 Ubuntu Bash 性能对比 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 14.04/16.04 与 Windows 10 周年版 Ubuntu Bash 性能对比 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 14.04/16.04 与 Windows 10 周年版 Ubuntu Bash 性能对比 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 14.04/16.04 与 Windows 10 周年版 Ubuntu Bash 性能对比 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/ubuntu vs ubuntu on windows","title":"Ubuntu 14.04/16.04 与 Windows 10 周年版 Ubuntu Bash 性能对比","tag":"201611","desc":""},"relativePath":"201611/ubuntu vs ubuntu on windows.md","filePath":"[post].md"}'),d={name:"201611/ubuntu vs ubuntu on windows.md"};function r(f,n,l,w,h,g){const a=i("Link");return o(),b("div",null,[n[21]||(n[21]=t("h1",{id:"ubuntu-14-04-16-04-与-windows-10-周年版-ubuntu-bash-性能对比",tabindex:"-1"},[p("Ubuntu 14.04/16.04 与 Windows 10 周年版 Ubuntu Bash 性能对比 "),t("a",{class:"header-anchor",href:"#ubuntu-14-04-16-04-与-windows-10-周年版-ubuntu-bash-性能对比","aria-label":"Permalink to “Ubuntu 14.04/16.04 与 Windows 10 周年版 Ubuntu Bash 性能对比”"},"​")],-1)),t("p",null,[n[2]||(n[2]=p("今年初，当 Microsoft 和 Canonical 发布 ",-1)),e(a,{href:"http://www.phoronix.com/scan.php?page=news_item&px=Ubuntu-User-Space-On-Win10"},{default:u(()=>[...n[0]||(n[0]=[p("Windows 10 Bash 和 Ubuntu 用户空间",-1)])]),_:1}),n[3]||(n[3]=p("，我尝试做了一些初步性能测试 ",-1)),e(a,{href:"http://www.phoronix.com/scan.php?page=article&item=windows-10-lxcore&num=1"},{default:u(()=>[...n[1]||(n[1]=[p("Ubuntu on Windows 10 对比 原生 Ubuntu",-1)])]),_:1}),n[4]||(n[4]=p("，这次我发布更多的，关于原生纯净的 Ubuntu 和基于 Windows 10 的基准对比。",-1))]),n[22]||(n[22]=t("p",null,[t("img",{src:"http://www.phoronix.net/image.php?id=windows10-anv-wsl&image=windows_wsl_1_med",alt:"Windows 的 Linux 子系统"})],-1)),n[23]||(n[23]=t("p",null,"Windows 的 Linux 子系统测试完成了所有测试，并随着 Windows 10周年更新放出。 默认的 Ubuntu 用户空间还是 Ubuntu 14.04，但是已经可以升级到 16.04。所以测试首先在 14.04 测试，完成后将系统升级升级到 16.04 版本并重复所有测试。完成所有基于 Windows 的 Ubuntu 子系统测试后，我在同样的系统上干净地安装了 Ubuntu 14.04.5 和 Ubuntu 16.04 LTS 来做性能对比。",-1)),n[24]||(n[24]=t("p",null,[t("img",{src:"http://www.phoronix.net/image.php?id=windows10-anv-wsl&image=windows_wsl_2_med",alt:"Ubuntu"})],-1)),n[25]||(n[25]=t("p",null,"配置为 Intel i5 6600K Skylake，16G 内存和 256G 东芝 ssd，测试过程中每个操作系统都采用其原生默认配置和软件包。",-1)),n[26]||(n[26]=t("p",null,[t("img",{src:"https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&sha=09989b3&p=2",alt:"Phoronix 测试套件"})],-1)),t("p",null,[n[6]||(n[6]=p("这次 Ubuntu/Bash on Windows 和原生 Ubuntu 对比测试，采用开源软件 ",-1)),e(a,{href:"http://www.phoronix-test-suite.com/"},{default:u(()=>[...n[5]||(n[5]=[p("Phoronix 测试套件",-1)])]),_:1}),n[7]||(n[7]=p("，完全自动化并可重复测试。",-1))]),n[27]||(n[27]=m('<p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=186c4d0&amp;c=a8c914bf9b64cf67abc65e319f8e71c7951fb1aa&amp;p=0" alt="SQLite 嵌入式数据库基准测试"></p><p>首先是 SQLite 嵌入式数据库基准测试。这方面开箱即用的 Ubuntu/Bash on Windows 性能是相当的慢，但是如果将环境从 14.04 升级到 16.04 LTS，性能会快很多。然而，对于繁重磁盘操作的任务，原生 Ubuntu Linux 几乎比 Windows 的子系统 Linux 快了近 2 倍。</p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=fa40825&amp;c=0912dc3f6d6a9f36da09fdd4c0cf4e330fa40f90&amp;p=0" alt="编译测试：编译"></p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=8419652&amp;c=9b9f6b0822ed5b9dc2977a7f2faf499fce4fba23&amp;p=0" alt="编译测试：初始创建"></p><p>编译测试作为额外的繁重磁盘操作测试显示，定制的 Windows 子系统真的成倍的限制了 Ubuntu 性能。</p><p>接下来，是一些使用 Stream 的基本的系统内存速度测试：</p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=9560e6f&amp;c=ebbc6937fa8daf0540e0df353432a29f938cf7ed&amp;p=0" alt="Stream：复制"></p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=63fa8d6&amp;c=88cd58f9eca6d3a09699d60d9f877529113fb1bc&amp;p=0" alt="Stream：缩放"></p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=5a2e9d2&amp;c=d37eee4c9394fa8104e7e49e26c964af70ec326b&amp;p=0" alt="Stream：添加"></p><p>奇怪的是，这些 Stream 内存的基准测试显示 Ubuntu on Windows 的性能比原生的 Ubuntu 好！这个现象同时发生在基于同样的 Windows 却环境不同的 14.04 和 16.04 LTS 上。</p><p>接下来，是一些繁重 CPU 操作测试。</p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=ee1f01f&amp;c=3e9a67230e0e081b99ee3237e702c0b40ee73d60&amp;p=0" alt="Dolfyn 科学测试"></p><p>通过 Dolfyn 科学测试，Ubuntu On Windows 和原生 Ubuntu 之间的性能其实是相当接近的。 对于 Ubuntu 16.04，由于较新的 GCC 编译器性能衰减，两个平台上的性能都较慢。</p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=dd69257&amp;c=0e31babb8b96be1ae38ea739fbb1346bf9bc4b07&amp;p=0" alt="Fhourstones 测试"></p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=a02416b&amp;c=c8abb70dee982dd494fb1891bd9dc154fa7a7f47&amp;p=0" alt="John The Ripper 测试"></p><p>透过 Fhourstones 测试和 John The Ripper 测试表明，通过在 Windows 的 Linux 子系统运行的 Ubuntu 的性能可以非常接近裸机 Ubuntu Linux 性能！</p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=3140e3c&amp;c=f4bf6330a7d58b5939c61cbd91fe5db379c1592a&amp;p=0" alt="x264 测试：H264视频编码"></p><p>类似于 Stream 测试，x264 结果是另一个奇怪的情况，其中最好的性能实际上是使用 Linux 子系统的 Ubuntu On Windows！</p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=ad12f0b&amp;c=f50c829c97d731f6926c5a874cf83f8fc5440067&amp;p=0" alt="Linux 内核编译时间"></p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=8b7a7ca&amp;c=3de3e8537d08665e8a41380b6b2298c09f408fa0&amp;p=0" alt="PHP 编译时间"></p><p>计时编译基准测试非常利于裸机 Ubuntu Linux。这是应该是由于大型程序编译需要大量读写磁盘，在先前测试已经发现了，这是基于 Windows 的 Linux 子系统缓慢的一大领域。</p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=25892d8&amp;c=f6cd3fa4a3497e3d2663106e0bf3fcd227f9b9a3&amp;p=0" alt="Crafty"></p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=2ea1062&amp;c=fbbec58a6aa1f3fb8dbc55e3de612afc99c666f7&amp;p=0" alt="FLAC 音频编码"></p><p><img src="https://openbenchmarking.org/embed.php?i=1608096-LO-BASHWINDO87&amp;sha=4899bb2&amp;c=80df0e1e749910ebd84b0d6c2688316e5cfb8cda&amp;p=0" alt="OpenSSL"></p><p>许多其他的通用开源基准测试表明，严格的针对 CPU 的测试，Windows 子系统的 Ubuntu 的性能是很接近的，甚至是与原生安装在实际硬件中的 Ubuntu Linux 相等。</p><p>最新的 Windows 的 Linux 子系统，测试结果实际上相当令人印象深刻。让人沮丧的仅仅只是持续缓慢的磁盘/文件系统性能，但是对于受 CPU 限制的工作负载，结果是非常引人注目的。还有很罕见的情况， x264 和 Stream 测试，Ubuntu On Windows 上的性能看起来明显优于运行在实际硬件上 的Ubuntu Linux。</p><p>总的来说，体验是十分愉快的，并且在 Ubuntu/Bash on Windows 也没有遇到任何其他的 bug。如果你有还兴趣了解更多关于 Windows 和 Linux 的基准测试，欢迎留言讨论。</p><hr>',28)),t("p",null,[n[9]||(n[9]=p("via: ",-1)),e(a,{href:"https://www.phoronix.com/scan.php?page=article&item=windows10-anv-wsl&num=1"},{default:u(()=>[...n[8]||(n[8]=[p("https://www.phoronix.com/scan.php?page=article&item=windows10-anv-wsl&num=1",-1)])]),_:1})]),t("p",null,[n[13]||(n[13]=p("作者：",-1)),e(a,{href:"http://www.michaellarabel.com/"},{default:u(()=>[...n[10]||(n[10]=[p("Michael Larabel",-1)])]),_:1}),n[14]||(n[14]=p(" 译者：",-1)),e(a,{href:"http://vicyu.net"},{default:u(()=>[...n[11]||(n[11]=[p("VicYu/Vic020",-1)])]),_:1}),n[15]||(n[15]=p(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:u(()=>[...n[12]||(n[12]=[p("wxy",-1)])]),_:1})]),t("p",null,[n[18]||(n[18]=p("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...n[16]||(n[16]=[p("LCTT",-1)])]),_:1}),n[19]||(n[19]=p(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:u(()=>[...n[17]||(n[17]=[p("Linux中国",-1)])]),_:1}),n[20]||(n[20]=p(" 荣誉推出",-1))])])}const x=s(d,[["render",r]]);export{W as __pageData,x as default};
